def ctx(text, kw, w=500, maxn=6):
    out=[]
    for m in list(re.finditer(kw, text, flags=re.I))[:maxn]:
        s=max(0,m.start()-w); e=min(len(text), m.end()+w)
        out.append(text[s:e].replace("\n"," "))
    return out
